# ============================================================================\n# U10. zip 為何只能用一次？（1.8）\n# ============================================================================\n# 本題揭示了一個常見的陷阱：zip() 返回的是迭代器，可以逐次取值，\n# 但第一次消耗（遍歷）後，迭代器就會耗盡，無法再次使用。\n# ============================================================================\n\nprint(\"【一上一下的故事】\")\nprint(\"=\" * 50)\nprint()\n\nprices = {'A': 2.0, 'B': 1.0}\nprint(f\"股票價格：{prices}\\n\")\n\nprint(\"需求：找到最低價和最高價\")\nprint()\n\nprint(\"\\n\" + \"=\" * 50)\nprint(\"【第一次嘗試 - 失敗案例】\")\nprint(\"=\" * 50)\nprint()\n\nprint(\"代碼：\")\nprint(\"\"\"\nz = zip(prices.values(), prices.keys())\nmin_val = min(z)    # OK\nmax_val = max(z)    # 失敗！\n\"\"\")\nprint()\n\nz = zip(prices.values(), prices.keys())\nprint(f\"z = zip(prices.values(), prices.keys())\")\nprint(f\"z 的型別：{type(z).__name__}  # 迭代器\\n\")\n\nprint(\"執行第 1 次操作：min(z)\")\nmin_val = min(z)\nprint(f\"  結果：{min_val}\")\nprint(f\"  說明：min() 遍歷迭代器取出最小值\\n\")\n\nprint(\"執行第 2 次操作：max(z)\")\ntry:\n    max_val = max(z)\n    print(f\"  結果：{max_val}\")\nexcept ValueError as e:\n    print(f\"  ✗ 錯誤：{e}\")\n    print()\n    print(\"  原因：\")\n    print(\"    1. zip(a, b) 返回的是迭代器（iterator）物件\")\n    print(\"    2. 迭代器一旦遍歷完，就會耗盡\")\n    print(\"    3. min() 已經消耗了迭代器的所有元素\")\n    print(\"    4. max() 試圖遍歷時，發現迭代器已經是空的\")\n    print(\"    5. ValueError：max() arg is an empty sequence\")\n    print()\n\nprint(\"\\n\" + \"=\" * 50)\nprint(\"【解決方案】\")\nprint(\"=\" * 50)\nprint()\n\nprint(\"\\n【方案 1】轉換為 list（最簡單）\")\nz_list = list(zip(prices.values(), prices.keys()))\nprint(f\"z_list = list(zip(prices.values(), prices.keys()))\")\nprint(f\"z_list = {z_list}\\n\")\n\nmin_result = min(z_list)\nmax_result = max(z_list)\nprint(f\"min(z_list) = {min_result}\")\nprint(f\"max(z_list) = {max_result}\")\nprint(\"✓ 成功！list 可以多次遍歷\")\nprint()\n\nprint(\"\\n【方案 2】分別建立 zip（如果只用一次）\")\nz1 = zip(prices.values(), prices.keys())\nz2 = zip(prices.values(), prices.keys())  # 建立新的迭代器\nmin_result = min(z1)\nmax_result = max(z2)\nprint(f\"用 z1 計算 min：{min_result}\")\nprint(f\"用 z2 計算 max：{max_result}\")\nprint(\"✓ 成功！每個迭代器只用一次\")\nprint()\n\nprint(\"\\n【方案 3】（推薦）一次用完並保存\")\nmin_val, min_key = min(zip(prices.values(), prices.keys()))\nprint(f\"第一次用 zip 計算最小值\")\nprint(f\"結果：最低價格 {min_val}，股票 {min_key}\")\nprint()\n\nmax_val, max_key = max(zip(prices.values(), prices.keys()))\nprint(f\"第二次用新的 zip 計算最大值\")\nprint(f\"結果：最高價格 {max_val}，股票 {max_key}\")\nprint()\n\nprint(\"\\n\" + \"=\" * 50)\nprint(\"【迭代器 vs 列表】\")\nprint(\"=\" * 50)\nprint(\"\"\"\n迭代器的特性：\n✓ 延遲求值 - 按需生成元素，節省記憶體\n✓ 適合大資料集 - 無需一次性載入全部資料\n✗ 一次性消耗 - 遍歷後無法重複使用\n✗ 無法 len() - 長度未知\n\n列表的特性：\n✓ 可多次遍歷 - 想用幾次就用幾次\n✓ 支援 len() - 可以查詢長度\n✗ 記憶體占用 - 一次性載入所有資料\n✗ 適合小資料集 - 對大資料集可能導致記憶體溢出\n\n選擇建議：\n✓ 需要多次操作 → list（或 itertools.tee()）\n✓ 只用一次，資料量大 → 迭代器（zip、filter、map）\n✓ 無法確定 → list（保險起見）\n\"\"\")\n\nprint(\"\\n\" + \"=\" * 50)\nprint(\"【常見誤區】\")\nprint(\"=\" * 50)\nprint(\"\"\"\n❌ 誤區 1：zip() 是函式，每次都會建立新迭代器\n  z = zip(a, b)\n  if condition:\n      val = min(z)  # 消耗迭代器\n  else:\n      val = max(z)  # 這時 z 已經耗盡，會報錯\n\n❌ 誤區 2：以為迭代器可以 reset\n  z = zip(a, b)\n  list1 = list(z)  # 消耗迭代器\n  list2 = list(z)  # 空列表，不能 reset！\n\n❌ 誤區 3：zip() 和 zipfile 混淆\n  zip(a, b)      # 內建函式 - 迭代器\n  zipfile.ZipFile # 檔案壓縮模組 - 不同概念\n\n✓ 最佳實踐：\n  1. 如果只用一次，直接用迭代器\n  2. 如果要用多次，轉換為 list\n  3. 複雜邏輯時，直接用 list（可靠性優先）\n\"\"\")"
